from typing import List, Tuple


def find_closest_elements(numbers: List[float]) -> Tuple[float, float]:
    if len(numbers) < 2 or not all(isinstance(num, float) for num in numbers):
        raise ValueError("Input list must have a minimum length of two and contain only float numbers.")

    min_diff = float('inf')
    closest_pair = None

    for i in range(len(numbers)):
        for j in range(i+1, len(numbers)):
            diff = abs(numbers[i] - numbers[j])
